-- rewards-v2: rewards-v1 plus one rule. A second practice on the same scope within an hour of the first
-- never earns more points than the first. The numbers equal REWARD_POLICY_V2 (a test keeps the two equal).
-- rewards-v1 is retired, never changed: its ledger entries stay explainable by the version they recorded.
UPDATE reward_policies SET status = 'retired' WHERE version = 'rewards-v1';--> statement-breakpoint
